def findPaths(m, n):
    # Initialize the matrix with 0's
    matrix = [[0 for x in range(n)] for y in range(m)]

    # Fill the first row with 1's
    for i in range(n):
        matrix[0][i] = 1

    # Fill the first column with 1's
    for i in range(m):
        matrix[i][0] = 1

    # Fill the remaining cells with the sum of the cell above and the cell to the left
    for i in range(1, m):
        for j in range(1, n):
            matrix[i][j] = matrix[i-1][j] + matrix[i][j-1]

    # Return the value in the bottom right corner
    return matrix[m-1][n-1]

