def post_order_traversal(tree):
    if not tree:
        return []
    stack = [0]
    result = []
    while stack:
        index = stack.pop()
        result.append(tree[index])
        left_index = 2*index + 1
        right_index = 2*index + 2
        if left_index < len(tree):
            stack.append(left_index)
        if right_index < len(tree):
            stack.append(right_index)
    return result[::-1]

