def odd_even_sort(array):
    n = len(array)
    sorted = False
    while not sorted:
        sorted = True
        # Perform even indexed comparison and swap
        for i in range(0, n-1, 2):
            if array[i] > array[i+1]:
                array[i], array[i+1] = array[i+1], array[i]
                sorted = False
        # Perform odd indexed comparison and swap
        for i in range(1, n-1, 2):
            if array[i] > array[i+1]:
                array[i], array[i+1] = array[i+1], array[i]
                sorted = False
    return array

