from collections import defaultdict

def sequence_reconstruction(org, seqs):
    dst, src, nodes = defaultdict(set), defaultdict(set), set()
    for seq in seqs:
        nodes |= set(seq)
        for i, node in enumerate(seq[1:]):
            src[node].add(seq[i])
            dst[seq[i]].add(node)
    if len(nodes) != len(org):
        return False
    q, path = [node for node in range(1, len(org)+1) if not src[node]], []
    while len(q) == 1:
        node = q.pop()
        path.append(node)
        for nei in dst[node]:
            src[nei].remove(node)
            if not src[nei]:
                q.append(nei)
    return path == org

def cutRod(price, n):
