    dp = [[0 for _ in range(n + 1)] for _ in range(n+1)] 
    for i in range(1,n+1):
        for j in range(1,n+1):
            if j >= lenth[i-1]:
                dp[i][j] = max(price[i-1] + dp[i][j - lenth[i-1]] , dp[i-1][j])
