def insert_node(root, value, result, result_index):
    if root is None:
        root = TreeNode(value)
    elif value <= root.value:
        root.count += 1
        root.left = insert_node(root.left, value, result, result_index)
    else:
        result[result_index] += root.count + 1
        root.right = insert_node(root.right, value, result, result_index)
    return root

from collections import Counter

def can_split(nums):
    count = Counter(nums)
    tail = {}

    for n in nums:
        if count[n] == 0:
            continue
        elif tail.get(n-1, 0) > 0:
            tail[n-1] -= 1
            tail[n] = tail.get(n, 0) + 1
        elif count.get(n+1, 0) > 0 and count.get(n+2, 0) > 0:
            count[n+1] -= 1
            count[n+2] -= 1
            tail[n+2] = tail.get(n+2, 0) + 1
        else:
            return False
        count[n] -= 1
    return True

