def wordFormation(text: str, word: str) -> int:
    tmp = {k: 0 for k in word}

    for v in text:
        if v in tmp:
            tmp[v] += 1

    for k in tmp:
        if tmp[k] < word.count(k):
            return 0 if tmp[k] == 0 else tmp[k] // word.count(k)

    return min(tmp[k] // word.count(k) for k in tmp)

