        if lis[i] > lis[i + 1]:
            lis[i] = lis[i + 1]
            break
    return judge(lis)

def judge(lis):
    for i in range(len(lis) - 1):
        if lis[i] > lis[i + 1]:
            return False
    return True

def max_Product_Subarray(nums):
    if not nums:
        return 0
    n = len(nums)
    max_dp = [0]*n
    min_dp = [0]*n
    max_dp[0] = min_dp[0] = nums[0]
    for i in range(1, n):
        max_dp[i] = max(nums[i], max_dp[i-1]*nums[i], min_dp[i-1]*nums[i])
        min_dp[i] = min(nums[i], max_dp[i-1]*nums[i], min_dp[i-1]*nums[i])
    return max(max_dp)

