import sys

def minimum_coins(coins, amount):
    dp = [sys.maxsize] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        for coin in coins:
            if i >= coin:
                dp[i] = min(dp[i], dp[i - coin] + 1)
    return dp[amount] if dp[amount] != sys.maxsize else -1

