def find_ceiling(arr, target):
    left, right = 0, len(arr) - 1
    ceiling = None
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return arr[mid]
        elif arr[mid] < target:
            left = mid + 1
        else:
            ceiling = arr[mid]
            right = mid - 1
    return ceiling

