def find_rotate_index(nums):
    if not nums:
        return -1
    if nums[0] < nums[-1]:
        return 0
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] > nums[mid + 1]:
            return mid + 1
        else:
            if nums[mid] < nums[0]:
                right = mid - 1
            else:
                left = mid + 1

