def mergeIntervals(intervals1, intervals2):
    merged_intervals = intervals1 + intervals2
    merged_intervals.sort(key=lambda x: (x[0], x[1]))

    i = 0

    while i < len(merged_intervals) - 1:
        if merged_intervals[i][1] >= merged_intervals[i+1][1]:
            del merged_intervals[i+1]
        elif merged_intervals[i][1] < merged_intervals[i+1][1] and merged_intervals[i][1] >= merged_intervals[i+1][0]:
            merged_intervals[i][1] = merged_intervals[i+1][1]
            del merged_intervals[i+1]
        else:
            i += 1
    return merged_intervals

