def check_n_queens(board):
    n = len(board)
    if n == 0:
        return False

    # Check rows and columns
    for i in range(n):
        if sum(board[i]) > 1:
            return False
        column_sum = sum([board[j][i] for j in range(n)])
        if column_sum > 1:
            return False

    # Check diagonals
    for i in range(-n + 1, n):
        diagonal_sum1 = sum([board[i - j][j] for j in range(max(0, i), min(n, n + i))])
        if diagonal_sum1 > 1:
            return False
        diagonal_sum2 = sum([board[j][i + j] for j in range(max(0, -i), min(n, n - i))])
        if diagonal_sum2 > 1:
            return False

    return True

def can_split_array(arr):
    total_sum = sum(arr)
    if total_sum % 2 != 0:
        return False

    target_sum = total_sum // 2
    n = len(arr)
    dp = [[False] * (target_sum + 1) for _ in range(n + 1)]
    dp[0][0] = True

    for i in range(1, n + 1):
        for j in range(target_sum + 1):
            if j < arr[i - 1]:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - arr[i - 1]]

    return dp[n][target_sum]

def is_valid_brackets(s: str) -> bool:
    bracket_map = {")": "(", "]": "[", "}": "{"}
    open_brackets = set(["(", "[", "{"])
    stack = []

    for char in s:
        if char in open_brackets:
            stack.append(char)
        elif char in bracket_map:
            if stack == [] or bracket_map[char] != stack.pop():
                return False
        else:
            return False

    return stack == []

