def postorder_traversal(root):
  if root is None:
    return []
  stack = [root]
  ret = []
  while (len(stack)) > 0:
    node = stack.pop()
    ret.append(node.val)
    if node.left is not None:
      stack.append(node.left)
    if node.right is not None:
      stack.append(node.right)
  return ret[::-1]

