def is_valid_ISBN10(isbn):
    if len(isbn) != 10:
        return False
    sum = 0
    for i in range(9):
        if isbn[i].isdigit():
            sum += int(isbn[i]) * (i+1)
        else:
            return False
    if isbn[9].isdigit():
        sum += int(isbn[9]) * 10
    elif isbn[9] == 'X':
        sum += 10 * 10
    else:
        return False
    return sum % 11 == 0

