        return "No"
    sum = 0
    for i in range(9):
        if not isbn[i].isdigit():
            return "No"
        sum += int(isbn[i]) * (i + 1)
    if isbn[9].isdigit():
        sum += int(isbn[9]) * 10
    elif isbn[9].upper() == 'X':
        sum += 10 * 10
    else:
        return "No"
    if sum % 11 == 0:
        return "Yes"
