from typing import List

def max_envelopes(envelopes: List[List[int]]) -> int:
    #if width are same, sort the height in descending order
    envelopes.sort(key= lambda x:(x[0],-x[1]))
    #print(envelopes)  [[2, 3], [5, 4], [6, 7], [6, 4]]

    dp = [0] * len(envelopes)
    max_len = 0

    def bin_search(arr,start,end,target):
        while start < end:
            mid = start + (end-start) //2
            if arr[mid] == target:
                return mid
            elif arr[mid] > target:
                end = mid
            else:
                start = mid + 1

        return start

    for i in range(len(envelopes)):
        # find the index of height of envelope[i]
        index = bin_search(dp,0,max_len,envelopes[i][1])
        dp[index] = envelopes[i][1]

        if index == max_len:
            max_len += 1

    return max_len

def is_valid_utf8(data):
    def check_bytes(start, length):
        for i in range(start + 1, start + length + 1):
            if i >= len(data) or (data[i] & 0xC0) != 0x80:  # Check if it's a continuation byte
                return False
        return True

    i = 0
    while i < len(data):
        if (data[i] & 0x80) == 0:  # 1-byte character
            i += 1
        elif (data[i] & 0xE0) == 0xC0:  # 2-byte character
            if not check_bytes(i, 1):
                return False
            i += 2
        elif (data[i] & 0xF0) == 0xE0:  # 3-byte character
            if not check_bytes(i, 2):
                return False
            i += 3
        elif (data[i] & 0xF8) == 0xF0:  # 4-byte character
            if not check_bytes(i, 3):
                return False
            i += 4
        else:
            return False
    return True

