def is_bipartite(edges):
    graph = defaultdict(list)
    for edge in edges:
        graph[edge[0]].append(edge[1])
        graph[edge[1]].append(edge[0])
    color = [0] * len(graph)
    for i in range(len(graph)):
        if color[i] != 0: continue
        q = deque()
        q.append(i)
        color[i] = 1
        while q:
            cur = q.popleft()
            for e in graph[cur]:
                if color[e] != 0:
                    if color[cur] == color[e]:
                        return False
                else:
                    color[e] = -color[cur]
                    q.append(e)
    return True

