def find_zero_sum_triplets(nums: List[int]) -> List[List[int]]:
    nums = sorted(nums)
    unique_triplets = set()

    if ((nums[0] < 0 and nums[-1] < 0)
        or (nums[0] > 0 and nums[-1] > 0)):
        return []

    for i, val in enumerate(nums):
        if i > 0 and val == nums[i - 1]:
            continue

        left, right = i + 1, len(nums) - 1
        while left < right:
            triplet_sum = val + nums[left] + nums[right]
            if triplet_sum < 0:
                left += 1
            elif triplet_sum > 0:
                right -= 1
            else:
                sorted_triplet = tuple(sorted([val, nums[left], nums[right]]))
                if sorted_triplet not in unique_triplets:
                    unique_triplets.add(sorted_triplet)
                left += 1

    return [list(triplet) for triplet in unique_triplets]

