def zigzag_string(s, numRows):
    if numRows == 1:
        return s
    if len(s) <= numRows:
        return s
    pattern_numb = numRows * 2 - 2
    result = ''
    for i in range(numRows):
        result += s[i]
        start_point = pattern_numb - i
        if i == 0:
            start_point = pattern_numb
        while start_point < len(s) and i == 0:
            result += s[start_point]
            start_point += pattern_numb
        while start_point < len(s) and i != 0 and i != numRows-1:
            result += s[start_point]
            start_point += 2*i
            if start_point < len(s):
                result += s[start_point]
            start_point += 2*(numRows-i-1)
        if i == numRows-1:
            start_point = i + pattern_numb
        while start_point < len(s) and i == numRows-1:
            result += s[start_point]
            start_point += pattern_numb
    return result

