        return ""
    reverse_strs = [s[::-1] for s in strs]
    common = ''
    for i, c in enumerate(reverse_strs[0]):
        flag = True
        for s in reverse_strs[1:]:
            if i >= len(s) or s[i] != c:
                flag = False
                break
        if flag:
            common += c
        else:
            break
    return common[::-1]


