    for i in range(0,len(s)):
        if s[i] in cmap and cmap[s[i]] >= sub_start:
            sub_start = cmap[s[i]] + 1
            cmap[s[i]] = i
            max_len = max(max_len, i+1-sub_start)
        else: # s[i] not in cmap
            cmap[s[i]] = i
            max_len = max(max_len, i+1-sub_start)
    return(max_len)

