def evaluate_postfix(expression):
    stack = []
    for token in expression.split():
        if token.isdigit():
            stack.append(int(token))
        else:
            y, x = stack.pop(), stack.pop()
            if token == '+':
                stack.append(x + y)
            elif token == '-':
                stack.append(x - y)
            elif token == '*':
                stack.append(x * y)
            elif token == '/':
                stack.append(x // y)
    return stack.pop()

