def closestCost(baseCosts, toppingCosts, target):
    toppingCombinations = [sum(combo) for i in range(0, 3) for combo in combinations_with_replacement(toppingCosts, i)]

    closestSum = float('inf')
    for base in baseCosts:
        for toppingSum in toppingCombinations:
            currentSum = base + toppingSum
            if abs(target - currentSum) < abs(target - closestSum) or (abs(target - currentSum) == abs(target - closestSum) and currentSum < closestSum):
                closestSum = currentSum

    return closestSum

