        return 0

    asc = [1] * len(arr)
    desc = [1] * len(arr)

    for i in range(1, len(arr)):
        if arr[i] > arr[i - 1]:
            asc[i] = asc[i - 1] + 1
        elif arr[i] < arr[i - 1]:
            desc[i] = desc[i - 1] + 1

    max_len = max(asc[-1], desc[-1])

    for i in range(len(arr) - 2, -1, -1):
        if (arr[i] > arr[i + 1] and desc[i] < asc[i + 1] + 1) or (arr[i] < arr[i + 1] and asc[i] < desc[i + 1] + 1):
