def minimum_length_encoding(words):
    words.sort(reverse=True)
    s = words[0]
    words = words[1:]
    if len(words) == 0:
        return len(s)+1

    w_index = 0
    s_index = 0
    is_matching = False
    while w_index < len(words):
        word = words[w_index]
        for _str in word:
            if s[s_index] != _str:
                if is_matching:
                    is_matching = False
                    break
            else:
                is_matching = True
            if s_index >= len(s) -1:
                if not is_matching:
                    s += f"#{word}"
                else:
                    if s_index -1 != len(word):
                        s += f"#{word[s_index:]}"
                w_index +=1
                is_matching = False
                s_index = 0
                break
            s_index +=1   
    return len(s) + 1

