def subarray_divisible(nums, k):
    """
    :type nums: List[int]
    :type k: int
    :rtype: bool
    """
    prefix_sum = {0: -1}
    current_sum = 0
    for i in range(len(nums)):
        current_sum += nums[i]
        if k != 0:
            current_sum %= k
        if current_sum in prefix_sum:
            if i - prefix_sum[current_sum] > 1:
                return True
        else:
            prefix_sum[current_sum] = i
    return False

