def build_BST(nums):
    if not nums:
        return None
    root = TreeNode(nums[0])
    for num in nums[1:]:
        current = root
        while True:
            if num < current.val:
                if current.left is None:
                    current.left = TreeNode(num)
                    break
                else:
                    current = current.left
            else:
                if current.right is None:
                    current.right = TreeNode(num)
                    break
                else:
                    current = current.right
    return root

