def partition_equal_sum(nums):
    total_sum = sum(nums)
    # If total sum is odd, it cannot be partitioned into two equal sum subsets.
    if total_sum % 2 != 0:
        return False
    target = total_sum // 2
    dp = [False] * (target + 1)
    dp[0] = True
    # For each number in nums, update dp.
    for num in nums:
        for i in range(target, num - 1, -1):
            dp[i] = dp[i] or dp[i - num]
    return dp[target]

