class NumMatrix(object):

    def __init__(self, matrix):
        if not matrix or not matrix[0]:
            return
        rows = len(matrix)
        columns = len(matrix[0])
        self.dp = [[0 for _ in range(columns)] for _ in range(rows)]

        # 初始化0,0
        self.dp[0][0] = matrix[0][0]
        # 初始化第一行
        for _column in range(1, columns):
            self.dp[0][_column] = self.dp[0][_column - 1] + matrix[0][_column]
        # 初始化第一列
        for _row in range(1, rows):
            self.dp[_row][0] = self.dp[_row - 1][0] + matrix[_row][0]

        for _row in range(1, rows):
            for _column in range(1, columns):
                self.dp[_row][_column] = self.dp[_row - 1][_column] + self.dp[_row][_column - 1] + matrix[_row][_column] - self.dp[_row - 1][_column - 1]

    def sum_region(self, row1, col1, row2, col2):
        if row1 == 0 and col1 == 0:
            return self.dp[row2][col2]
        elif row1 == 0:
            return self.dp[row2][col2] - self.dp[row2][col1 - 1]
        elif col1 == 0:
            return self.dp[row2][col2] - self.dp[row1 - 1][col2]
        elif row1 >= 1 and col1 >= 1:
            return self.dp[row2][col2] - self.dp[row2][col1 - 1] - self.dp[row1 - 1][col2] + self.dp[row1 - 1][col1 - 1]

def sum_region(matrix, row1, col1, row2, col2):
    obj = NumMatrix(matrix)
    return obj.sum_region(row1, col1, row2, col2)

