def detect_cycle_undirected(n, edges, vertex_count, edge_count):
    graph = [[] for _ in range(vertex_count + 1)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def dfs(node, parent):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                if dfs(neighbor, node):
                    return True
            elif neighbor != parent:
                return True
        return False

    visited = [False] * (vertex_count + 1)
    for i in range(1, vertex_count + 1):
        if not visited[i]:
            if dfs(i, -1):
                return True
    return False

