def minimumLargestValue(arr, k):
    def enough(threshold):
        count = 1
        current_sum = 0
        for num in arr:
            current_sum += num
            if current_sum > threshold:
                current_sum = num
                count += 1
                if count > k:
                    return False
        return True

    low, high = max(arr), sum(arr)
    while low < high:
        mid = (low + high) // 2
        if enough(mid):
            high = mid
        else:
            low = mid + 1
    return low

