import heapq

def conveyor_belt(matrix: List[str], start: List[int], end: List[int]) -> int:
    R, C = len(matrix), len(matrix[0])
    dirs = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    signals = ['>', '<', 'v', '^']
    distances = [[float('inf')] * C for _ in range(R)]
    q = [(0, start[0], start[1])]
    while q:
        dis, r, c = heapq.heappop(q)
        if [r, c] == end:
            return dis
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C:
                w = +(signals.index(matrix[r][c]) != dirs.index((dr, dc)))
                if dis + w < distances[nr][nc]:
                    distances[nr][nc] = dis + w
                    heapq.heappush(q, (dis + w, nr, nc))

