def levelOrderSum(root):
    if not root:
        return []

    result = []
    queue = deque([root])

    while queue:
        level_sum = 0
        for i in range(len(queue)):
            node = queue.popleft()
            level_sum += node.val

            if node.left:
                queue.append(node.left)
