def canKPartitions(A, K):
    total_sum = sum(A)
    if total_sum % K != 0:
        return False
    target = total_sum // K
    remaining = [False] * len(A)
    def find_partition(start, remaining_sum, remaining_partitions):
        if remaining_partitions == 1:
            return True
        if remaining_sum == target:
            return find_partition(0, 0, remaining_partitions - 1)
        for i in range(start, len(A)):
            if not remaining[i] and remaining_sum + A[i] <= target:
                remaining[i] = True
                if find_partition(i + 1, remaining_sum + A[i], remaining_partitions):
                    return True
                remaining[i] = False
        return False
    return find_partition(0, 0, K)

