def num_diff_int(word: str) -> int:
    # 方法一：哈希集合 + 双指针
    # 时间复杂度：O(n)
    # 空间复杂度：O(n)
    n = len(word)
    count = set()
    i, j = 0, 0
    while i < n and j < n:
        while i < n and not word[i].isdigit():
            i += 1
        j = i
        while j < n and word[j].isdigit():
            j += 1
        if i != j:
            num = int(word[i:j].lstrip('0'))
            if num > 0:
                count.add(num)
        i = j
    return len(count)

def find_Quadruplets(nums, n):
