    for i in range(1, len(words)):
        prev = words[i-1]
        cur = words[i]
        n = min(len(prev), len(cur))
        if prev[:n] == cur[:n] and len(prev) > len(cur):
            return False
        for j in range(n):
            p = mapping[prev[j]]
            c = mapping[cur[j]]
            if p < c:
                break
            elif p > c:
                return False
    return True

