def can_divide_into_consecutive_subsequences(nums: List[int]) -> bool:
    countMap = collections.Counter(nums)
    endMap = collections.Counter()

    for x in nums:
        if countMap[x] > 0:
            if endMap.get(x - 1, 0) > 0:
                countMap[x] -= 1
                endMap[x - 1] -= 1
                endMap[x] += 1

            else:
                if countMap.get(x + 1, 0) > 0 and countMap.get(x + 2, 0) > 0:
                    countMap[x] -= 1
                    countMap[x + 1] -= 1
                    countMap[x + 2] -= 1
                    endMap[x + 2] += 1
                else:
                    return False

    return True

