def check_square(matchsticks):
    if sum(matchsticks)%4 != 0: return False
    k = sum(matchsticks)//4
    seen = [0]*len(matchsticks)
    matchsticks.sort(reverse=True)

    def dfs(i, sm, group):
        if group==4: return True
        if sm>k: return False
        if sm==k: return dfs(0, 0, group+1)
        for j in range(i, len(matchsticks)):
            if not seen[j]:
                seen[j] = 1
                if dfs(j, sm+matchsticks[j], group): return True
                seen[j] = 0
        return False

    return dfs(0, 0, 0)

