def max_depth_bfs(tree):
    if not tree:
        return 0
    queue = deque([(0, 1)])
    max_depth = 0
    while queue:
        index, depth = queue.popleft()
        max_depth = max(max_depth, depth)
        left_index = 2*index + 1
        right_index = 2*index + 2
        if left_index < len(tree) and tree[left_index] is not None:
            queue.append((left_index, depth + 1))
        if right_index < len(tree) and tree[right_index] is not None:
            queue.append((right_index, depth + 1))
    return max_depth

