def palindrome_substring(s):
    if len(s) == 1:
        return s
    longest = ""
    for i in range(len(s)):
        # odd length
        left, right = i, i
        while left >= 0 and right < len(s) and s[left] == s[right]:
            if (right - left + 1) > len(longest):
                longest = s[left:right+1]
            left -= 1
            right += 1

        # even length
        left, right = i, i + 1
        while left >= 0 and right < len(s) and s[left] == s[right]:
            if (right - left + 1) > len(longest):
                longest = s[left:right+1]
            left -= 1
            right += 1
    return longest

from functools import lru_cache

def numUniqueBST(n: int) -> int:
    @lru_cache(None)
    def dfs(nodes):
        if nodes <= 1:
            return 1

        count = 0
        for root in range(1, nodes + 1):
            left_subtrees = dfs(root - 1)
            right_subtrees = dfs(nodes - root)
            count += left_subtrees * right_subtrees

        return count

    return dfs(n)

