def is_valid_tic_tac_toe(board):
    def check_line(line):
        return sum([1 for c in line if c == 'X']) <= 3 and sum([1 for c in line if c == 'O']) <= 3

    # Check rows
    for row in board:
        if not check_line(row):
            return False

    # Check columns
    for col in range(3):
        col_line = ''.join([board[row][col] for row in range(3)])
        if not check_line(col_line):
            return False

    # Check diagonals
    if not check_line(board[0][0] + board[1][1] + board[2][2]) or not check_line(board[0][2] + board[1][1] + board[2][0]):
        return False

    # Check X and O quantity
    x_count = sum([1 for row in board for c in row if c == 'X'])
    o_count = sum([1 for row in board for c in row if c == 'O'])
    if x_count != o_count and x_count != o_count + 1:
        return False

    return True

