def check_subarray_divisible(nums, k):
    index={}
    remainder = 0
    index[0] = -1
    for i in range(len(nums)):
        remainder = (remainder + nums[i]) % k
        if remainder in index:
            if i - index[remainder] > 1:
                return True
        else:
            index[remainder] = i
    return False

def first_last_position(nums, target):
    def binary_search(left):
        lo, hi = 0, len(nums)
        while lo < hi:
            mid = (lo + hi) // 2
            if nums[mid] > target or (left and nums[mid] == target):
                hi = mid
            else:
                lo = mid+1
        return lo

    left_idx = binary_search(True)
    if left_idx == len(nums) or nums[left_idx] != target:
        return [-1, -1]
    right_idx = binary_search(False) - 1
    return [left_idx, right_idx]

