from collections import Counter

def find_word_in_board(board: List[List[str]], word: str) -> bool:
    if len(word) > len(board) * len(board[0]):
        return False

    word_count = Counter(word)
    board_flatten = sum(board, [])
    board_count = Counter(board_flatten)
    for letter, letter_count in word_count.items():
        if board_count[letter] < letter_count:
            return False

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    row, col = len(board), len(board[0])
    visited = set()

    def dfs(x, y, index):
        if index == len(word):
            return True
        if x < 0 or x >= row or y < 0 or y >= col or (x, y) in visited or board[x][y] != word[index]:
            return False
        visited.add((x, y))
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if dfs(nx, ny, index + 1):
                return True
        visited.remove((x, y))
        return False

    for i in range(row):
        for j in range(col):
            if board[i][j] == word[0]:
                if dfs(i, j, 0):
                    return True
    return False

def fibonacci_recursion(n):
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci_recursion(n-1) + fibonacci_recursion(n-2)

def beautiful_arrangements(n: int) -> int:
    arr = [(i+1) for i in range(n)]
    res = 0

    def solve(arr, i):
        if i == n+1:
            nonlocal res
            res += 1
            return
        for j, ch in enumerate(arr):
            if ch % i == 0 or i % ch == 0:
                solve(arr[:j] + arr[j+1:], i+1)

    solve(arr, 1)
    return res

