def minimum_capacity(tasks, time_slots):
    left, right = max(tasks), sum(tasks)
    while left < right:
        mid = (left + right) // 2
        need, load = 1, 0
        for task in tasks:
            if load + task > mid:
                need += 1
                load = 0
            load += task
        if need <= time_slots:
            right = mid
        else:
            left = mid + 1
    return left

