def railway_platform(arrivals):
    arrivals.sort()
    platforms_needed = 1
    max_platforms = 1
    platform_end_times = [arrivals[0][1]]
    for i in range(1, len(arrivals)):
        if arrivals[i][0] > platform_end_times[0]:
            platform_end_times.pop(0)
        else:
            platforms_needed += 1
        platform_end_times.append(arrivals[i][1])
        if platforms_needed > max_platforms:
            max_platforms = platforms_needed
    return max_platforms

