    result = []
    prev = None
    for num in sorted(count.keys()):
        for _ in range(count[num]):
            if prev is None or prev != num:
                result.append(num)
                prev = num
            else:
                return None
    return result

import re

def string_to_pig_latin(s):
    vowels = 'aeiou'
    # Check if the word ends with punctuation
    punctuation = re.findall(r'[^\w\s]$', s)
    # Remove punctuation for processing
    s = re.sub(r'[^\w\s]', '', s)

    if s[0].lower() in vowels:
        # Rule 1: Starts with a vowel
        result = s + "way"
    else:
        # Rule 2: Starts with a consonant
        for i in range(1, len(s)):
            if s[i].lower() in vowels:
                result = s[i:] + s[:i] + "ay"
                break
        else:
            # If no vowel is found, treat the whole word as a consonant cluster
            result = s + "ay"

    # Re-add punctuation if it existed
    if punctuation:
        result += punctuation[0]

    return result

def sort_dutch_flag(arr):
    low, mid, high = 0, 0, len(arr) - 1

    while mid <= high:
        if arr[mid] == 0:
            arr[low], arr[mid] = arr[mid], arr[low]
            low += 1
            mid += 1
        elif arr[mid] == 1:
            mid += 1
        else:
            arr[mid], arr[high] = arr[high], arr[mid]
            high -= 1
    return arr

from typing import List

def find_number_of_islands(grid: List[List[str]]) -> int:
    if not grid:
        return 0

    rows, cols = len(grid), len(grid[0])
    visit = set()
    islands = 0

    def dfs(r, c):
        if (r < 0 or c < 0 or r >= rows or c >= cols or grid[r][c] == "0" or (r, c) in visit):
            return
        visit.add((r, c))
        directions = [[0, 1], [1, 0], [-1, 0], [0, -1]]
        for dr, dc in directions:
            dfs(r + dr, c + dc)

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == "1" and (r, c) not in visit:
                dfs(r, c)
                islands += 1
    return islands


