def continuous_subarray_sum(nums, k):
    hash_map = {0: -1}
    total = 0
    for i, num in enumerate(nums):
        total += num
        if k != 0:
            total %= k
        if total in hash_map:
            if i - hash_map[total] > 1:
                return True
        else:
            hash_map[total] = i
    return False

