def count_valid_parentheses_strings(n):
    if n == 0:
        return 1
    count = [0] * (n+1)
    count[0] = 1
    for i in range(1, n+1):
        for j in range(i):
            count[i] += count[j] * count[i-1-j]
    return count[n]

def find_next_greater_elements(nums):
    stack = []
    result = [-1] * len(nums)

    for i in range(0, len(nums)):
        while stack and nums[stack[-1]] < nums[i]:
            index = stack.pop()
            result[index] = nums[i]
        stack.append(i)

    return result

from collections import defaultdict

def longest_k_substring(s, k):
    n = len(s)
    ans = -1

    map = defaultdict(int)
    j = 0

    for i in range(n):
        map[s[i]] += 1

        if len(map) == k:
            ans = max(ans, i - j + 1)


        while len(map) > k:
            map[s[j]] -= 1

            if map[s[j]] == 0:
                del map[s[j]]

            j += 1

        if len(map) == k:
            ans = max(ans, i - j + 1)

    return ans

def min_distance(arr, x):
    n = len(arr)
    min_dist = n
    prev = -1
    for i in range(n):
        if arr[i] == x:
            if prev != -1:
                if min_dist > i - prev:
                    min_dist = i - prev
            prev = i
    if min_dist == n:
        return -1
    return min_dist

def numTilings(n: int) -> int:
    if n == 1:
        return 1
    elif n == 2:
        return 2
    else:
        DP = [0] * (n + 1)
        DP[0] = DP[1] = 1
        DP[2] = 2
        for Index in range(3, n + 1):
            DP[Index] = DP[Index - 2] * 2 + DP[Index - 3]
        return DP[-1]

def find_in_cyclic_sorted(arr, target):
    n = len(arr)
    if n == 0:
        return -1
    if n == 1:
        return 0 if arr[0] == target else -1

    # Find the index of the smallest element
    start, end = 0, n - 1
    while start < end:
        mid = (start + end) // 2
        if arr[mid] > arr[end]:
            start = mid + 1
        else:
            end = mid

    # Binary search in the sorted part
    def binary_search(arr, target, start, end):
        while start <= end:
            mid = (start + end) // 2
            if arr[mid] == target:
                return mid
            elif arr[mid] < target:
                start = mid + 1
            else:
                end = mid - 1
        return -1

    if target >= arr[0]:
        return binary_search(arr, target, 0, start - 1)
    else:
        return binary_search(arr, target, start, n - 1)

