def longest_PalindromeSubseq(str):
  n = len(str)
  dp = [[0 for _ in range(n)] for _ in range(n)]

  for i in range(n - 1, -1, -1):
    dp[i][i] = 1
    for j in range(i + 1, n):
      if str[i] == str[j]:
        dp[i][j] = 2 + dp[i + 1][j - 1]
      else:
        dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

  return dp[0][n - 1]

