def filter_anagrams(words):
    anagram_groups = {}
    for word in words:
        sorted_word = ''.join(sorted(word))
        if sorted_word in anagram_groups:
            anagram_groups[sorted_word].append(word)
        else:
            anagram_groups[sorted_word] = [word]

    filtered_anagrams = [word for words in anagram_groups.values() if len(words) > 1 for word in words]
    return filtered_anagrams

def next_prime(n):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    prime = n + 1
    while not is_prime(prime):
        prime += 1
    return prime

