def max_island_area(matrix):
    if not matrix:
        return 0

    m, n = len(matrix), len(matrix[0])
    max_area = 0

    def bfs(i, j):
        area = 1
        queue = deque([(i, j)])
        matrix[i][j] = 0

        while queue:
            x, y = queue.popleft()

            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = x + dx, y + dy

                if 0 <= nx < m and 0 <= ny < n and matrix[nx][ny] == 1:
                    matrix[nx][ny] = 0
                    area += 1
                    queue.append((nx, ny))

        return area

    for i in range(m):
        for j in range(n):
            if matrix[i][j] == 1:
                max_area = max(max_area, bfs(i, j))

    return max_area

def can_form_rectangle(nums):
    perimeter = sum(nums)
    n = len(nums)
    if n < 4 or perimeter % 4 != 0:
        return False
    visited = [0] * n
    target = perimeter // 4

    def DFS(pos, fulledge, curlen):
        if fulledge == 3:
            return True
        if curlen > target:
            return False
        if curlen == target:
            return DFS(0, fulledge + 1, 0)

        for i in range(pos, n):
            if visited[i] == 1: continue
            visited[i] = 1
            if DFS(i + 1, fulledge, curlen + nums[i]):
                return True
            visited[i] = 0
        return False
    return DFS(0, 0, 0)

