def word_exist(board: List[List[str]], word: str) -> bool:
    def dfs(r, c, k):
        if not (0 <= r < len(board)) or not (0 <= c < len(board[0])) or board[r][c] != word[k]:
            return False
        if k == len(word) - 1:
            return True
        temp, board[r][c] = board[r][c], '/'
        found = dfs(r + 1, c, k + 1) or dfs(r - 1, c, k + 1) or dfs(r, c + 1, k + 1) or dfs(r, c - 1, k + 1)
        board[r][c] = temp
        return found

    for r in range(len(board)):
        for c in range(len(board[0])):
            if dfs(r, c, 0):
                return True
    return False

