    required = len(str2_dict)
    formed = 0
    window_counts = {}

    left, right = 0, 0
    min_length = float("inf")
    min_window = ""

    while right < len(str1):
        character = str1[right]
        window_counts[character] = window_counts.get(character, 0) + 1

        if character in str2_dict and window_counts[character] == str2_dict[character]:
