        return 0

    left, right = 0, len(elevations) - 1
    left_max, right_max = elevations[left], elevations[right]
    trapped_water = 0

    while left < right:
        if left_max < right_max:
            left += 1
            left_max = max(left_max, elevations[left])
            trapped_water += max(0, left_max - elevations[left])
        else:
