    for i in range(1, n+1):
        xor ^= i
    for num in arr:
        xor ^= num
    lowbit = xor & -xor
    a, b = 0, 0
    for num in arr:
        if num & lowbit:
            a ^= num
        else:
            b ^= num
    for i in range(1, n+1):
        if i & lowbit:
            a ^= i
        else:
            b ^= i
    for num in arr:
        if num == a:
            return [a, b]
    return [b, a]

