        while parent_dict[w] != w:
            w = parent_dict[w]
        return w

    for w1, w2 in pairs:
        r1, r2 = find(w1), find(w2)
        if r1 != r2:
            parent_dict[r1] = r2

    for w1, w2 in zip(words1, words2):
