def min_speed_on_time(dist, hour):
    m = len(dist)

    def check(speed):
        cost = 0
        for i in range(m):
            temp = dist[i] * 1.00 / speed
            if i != m - 1:
                cost += ceil(temp)
            else:
                cost += temp
        return cost <= hour

    if m > ceil(hour):
        return -1
    left, right = 1, max(max(dist), 1e7)
    while left < right:
        mid = (left + right) // 2
        if check(mid):
            right = mid
        else:
            left = mid + 1
    return int(left)

