    for c in s1:
        s1Count[c] += 1

    localCount = defaultdict(int)

    start = 0
    count = 0
    for end in range(len(s2)):
        endChar = s2[end]
        localCount[endChar] += 1

        if end - start + 1 == len(s1):
            if localCount == s1Count:
