from collections import deque

def is_cyclic_graph(numCourses, prerequisites):
    """
    :type numCourses: int
    :type prerequisites: List[List[int]]
    :rtype: bool
    """
    if not prerequisites or not prerequisites[0]:
        return False
    next_course = {i:[] for i in range(numCourses)}
    degree = [0 for i in range(numCourses)]

    for pre in prerequisites:
        degree[pre[0]] += 1
        next_course[pre[1]].append(pre[0])

    queue = deque()
    processed = []
    for key, value in enumerate(degree):
        if value == 0:
            queue.append(key)

    while queue:
        course = queue.popleft()
        if course is None:
            continue

        processed.append(course)
        for nextt in next_course[course]:
            degree[nextt] -= 1
            if degree[nextt] == 0:
                queue.append(nextt)

    return not len(processed) == numCourses

