from collections import Counter

def can_divide_in_subsequences(nums: List[int], k: int) -> bool:
    if len(nums) % k != 0:
        return False
    num_counts = Counter(nums)
    for num in sorted(num_counts):
        if num_counts[num] > 0:
            needed = num_counts[num]
            for i in range(num, num + k):
                if num_counts[i] < needed:
                    return False
                num_counts[i] -= needed
    return True

