    curSum = 0
    for i, n in enumerate(nums):
        curSum += n
        remainder = curSum % k
        if remainder not in remInd:
            remInd[remainder] = i  
        elif i - remInd[remainder] >1:
            return True
    return False

def diagonal_order(mat):
    m, n = len(mat), len(mat[0])
    res = []
    for i in range(m + n - 1):
        if i % 2 == 0:
            row = max(0, i - n + 1)
            col = i - row
            while row < m and col >= 0:
                res.append(mat[row][col])
                row += 1
                col -= 1
        else:
            col = min(i, n - 1)
            row = i - col
            while col >= 0 and row < m:
                res.append(mat[row][col])
                col -= 1
                row += 1
    return res

