from typing import List

def partition_palindrome(s: str) -> List[List[str]]:
    def dfs(s: str, start: int, stack: List[str], dp: List[List[bool]], result: List[List[str]]) -> None:
        if start == len(s):
            result.append(stack[:])
            return
        for i in range(start, len(s)):
            if s[i] == s[start] and (i <= start + 1 or dp[start + 1][i - 1]):
                dp[start][i] = True
                stack.append(s[start:i + 1])
                dfs(s, i + 1, stack, dp, result)
                stack.pop()
    result = []
    dp = [[False for _ in range(len(s))] for _ in range(len(s))]
    dfs(s, 0, [], dp, result)
    return result

def modify_numbers(numbers):
