def compute_levenshtein_distance(str1, str2):
    n1, n2 = len(str1), len(str2)
    dp = [[0] * (n2 + 1) for _ in range(n1 + 1)]
    for j in range(1, n2+1):
        dp[0][j] = dp[0][j-1] + 1
    for i in range(1, n1+1):
        dp[i][0] = dp[i-1][0] + 1
    for i in range(1, n1+1):
        for j in range(1, n2+1):
            if str1[i-1] == str2[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = min(dp[i][j-1], dp[i-1][j], dp[i-1][j-1]) + 1
    return dp[-1][-1]

def hasMatrixWordPath(matrix, word):
    rows, cols = len(matrix), len(matrix[0])
    book = [[0 for _ in range(cols)] for _ in range(rows)]

    def helper(r, c, word_index):
        if word_index == len(word):
            return True
        if r < 0 or c < 0 or r >= rows or c >= cols or book[r][c] == 1 or matrix[r][c] != word[word_index]:
            return False
        book[r][c] = 1
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if helper(nr, nc, word_index + 1):
                return True
        book[r][c] = 0
        return False

    for r in range(rows):
        for c in range(cols):
            if matrix[r][c] == word[0]:
                if helper(r, c, 0):
                    return True
    return False

