from collections import defaultdict, deque

def can_topologically_sort(num_vertices, edges):
    indegrees = [0] * num_vertices
    adjacency = defaultdict(list)
    for cur, pre in edges:
        indegrees[cur] += 1
        adjacency[pre].append(cur)
    queue = deque()
    for i in range(len(indegrees)):
        if not indegrees[i]: queue.append(i)
    while queue:
        pre = queue.popleft()
        num_vertices -= 1
        for cur in adjacency[pre]:
            indegrees[cur] -= 1
            if not indegrees[cur]: queue.append(cur)
    return not num_vertices

def valid_parentheses_combinations(n):
    """
    Calculate the total number of valid parentheses combinations for a given number of pairs.

    :param n: Number of pairs of parentheses
    :return: Number of valid combinations
    """
    if n == 0:
        return 1
    if n == 1:
        return 1
    dp = [0] * (n + 1)
    dp[0], dp[1] = 1, 1
    for i in range(2, n + 1):
        for j in range(i):
            dp[i] += dp[j] * dp[i - j - 1]
    return dp[n]

def get_pascal(row):
    current = [1]
    for i in range(row):
        prev = 1
        for j in range(1, i+1):
            tmp = current[j]
            current[j] += prev
            prev = tmp
        current += [1]
    return current

