def min_moves_to_power(n: int, base: int) -> int:
    """
    This function calculates the minimum number of moves required to convert 'n' into a power of 'base'.
    A move is defined as either multiplying or dividing 'n' by 'base'.
    """
    moves = 0
    while n != 1:
        if n % base == 0:
            n /= base
        else:
            n += 1 if n < base else -1
        moves += 1
    return moves

