def is_BST(root):
    def check(node, min_val, max_val):
        if node is None:
            return True
        if node.val <= min_val or node.val >= max_val:
            return False
        return check(node.left, min_val, node.val) and check(node.right, node.val, max_val)
    return check(root, float('-inf'), float('inf'))

