            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    prime_list = [i for i in range(start, end + 1) if is_prime(i)]
    return prime_list

def climb_Staircase(n):
    if n == 1 or n == 0:
        return 1
    elif n == 2:
        return 2

    dp = [0] * (n+1)
    dp[0], dp[1], dp[2] = 1, 1, 2
    for i in range(3, n+1):
        dp[i] = dp[i-1] + dp[i-2] + dp[i-3]
    return dp[n]

def longest_substring_with_repeated_chars(s: str) -> str:
    max_substring = ""
    current_substring = ""
    prev_char = ""
    char_count = 0
    for ch in s:
        if ch == prev_char:
            char_count += 1
            if char_count > 2:
                if len(current_substring) > len(max_substring):
                    max_substring = current_substring
                current_substring = prev_char * 2
                char_count = 1
        else:
            if len(current_substring) > len(max_substring):
                max_substring = current_substring
            current_substring = ch
            prev_char = ch
            char_count = 1
    if len(current_substring) > len(max_substring):
        max_substring = current_substring
    return max_substring

