def unique_pathsWithObstacles(obstacleGrid):
    M = len(obstacleGrid)
    N = len(obstacleGrid[0])

    if obstacleGrid[0][0] == 1:
        return 0

    obstacleGrid[0][0] = 1

    for i in range(1, M):
        obstacleGrid[i][0] = int(obstacleGrid[i][0] == 0 and obstacleGrid[i-1][0] == 1)

    for j in range(1, N):
        obstacleGrid[0][j] = int(obstacleGrid[0][j] == 0 and obstacleGrid[0][j-1] == 1)

    for i in range(1, M):
        for j in range(1, N):
            if obstacleGrid[i][j] == 0:
                obstacleGrid[i][j] = obstacleGrid[i-1][j] + obstacleGrid[i][j-1]
            else:
                obstacleGrid[i][j] = 0

    return obstacleGrid[-1][-1]

from collections import defaultdict

def max_substrings_without_repeating(s):
    intervals = defaultdict(list)
    for i, c in enumerate(s):
        intervals[c].append(i)
    for key, interv in intervals.items():
        left, right = interv[0], interv[-1] + 1
        tl, tr = left, right
        left, right = -1, -1
        while tl != left or tr != right:
            left, right = tl, tr
            for ch in set(s[tl:tr]):
                tl = min(tl, intervals[ch][0])
                tr = max(tr, intervals[ch][-1] + 1)
            if tl == left and tr == right:
                intervals[key] = [left, right]
                break
    sint = sorted(intervals.values(), key=lambda pair: pair[1])
    prev = 0
    output = []
    for start, end in sint:
        if start >= prev:
            output.append(s[start:end])
            prev = end
    return output

