import math

def gcd(x, y):
    while(y):
        x, y = y, x % y
    return x

def gcd_array(nlist):
    num1 = nlist[0]
    num2 = nlist[1]
    gcd_num = gcd(num1, num2)

    for i in range(2, len(nlist)):
        gcd_num = gcd(gcd_num, nlist[i])

    return gcd_num

