def nearest_smaller_elements(arr):
    stack = []
    result = []
    for i in range(len(arr)):
        while stack and stack[-1][0] >= arr[i]:
            stack.pop()
        if not stack:
            result.append(-1)
        else:
            result.append(stack[-1][0])
        stack.append((arr[i], i))
