from collections import deque

def find_minimum_moves(deadends, target):
    def turn(digit):
        return (str((int(digit) + 1) % 10), str((int(digit) - 1) % 10))

    def neighbors(state):
        for i in range(4):
            digit = state[i]
            for diff in turn(digit):
                yield state[:i] + diff + state[i+1:]

    dead = set(deadends)
    queue = deque([("0000", 0)])
    visited = {"0000"}

    while queue:
        state, steps = queue.popleft()
        if state == target:
            return steps
        if state in dead:
            continue
        for next_state in neighbors(state):
            if next_state not in visited:
                visited.add(next_state)
                queue.append((next_state, steps + 1))
    return -1

