from collections import deque

def can_print_matrix(targetGrid):
    def build_graph(colors):
        m, n = len(targetGrid), len(targetGrid[0])
        graph, indegree = {}, {}
        for color in colors:
            x1, y1, x2, y2 = m, n, -1, -1
            for i in range(m):
                for j in range(n):
                    if color == targetGrid[i][j]:
                        x1, y1 = min(x1, i), min(y1, j)
                        x2, y2 = max(x2, i), max(y2, j)
            if x2 == -1:
                continue
            for i in range(x1, x2 + 1):
                for j in range(y1, y2 + 1):
                    if targetGrid[i][j] != color:
                        if targetGrid[i][j] not in indegree:
                            indegree[targetGrid[i][j]] = 0
                        indegree[targetGrid[i][j]] += 1
                        if color not in graph:
                            graph[color] = set()
                        graph[color].add(targetGrid[i][j])
        return graph, indegree

    def topological_sort(graph, indegree):
        queue = deque([color for color in graph if color not in indegree])
        visited = set()
        while queue:
            color = queue.popleft()
            visited.add(color)
            for neighbor in graph.get(color, []):
                indegree[neighbor] -= 1
                if indegree[neighbor] == 0:
                    queue.append(neighbor)
        return len(visited) == len(graph)

    colors = set()
    for row in targetGrid:
        for color in row:
            colors.add(color)

    graph, indegree = build_graph(colors)
    return topological_sort(graph, indegree)

