def heapify(arr, n, i, is_max_heap=True):
    if is_max_heap:
        largest = i
    else:
        smallest = i
    l = 2 * i + 1
    r = 2 * i + 2

    if l < n:
        if is_max_heap:
            if arr[l] > arr[largest]:
                largest = l
        else:
            if arr[l] < arr[smallest]:
                smallest = l

    if r < n:
        if is_max_heap:
            if arr[r] > arr[largest]:
                largest = r
        else:
            if arr[r] < arr[smallest]:
                smallest = r

    if is_max_heap:
        if largest != i:
            arr[i], arr[largest] = arr[largest], arr[i]
            heapify(arr, n, largest, is_max_heap)
    else:
        if smallest != i:
            arr[i], arr[smallest] = arr[smallest], arr[i]
            heapify(arr, n, smallest, is_max_heap)

