def longest_palindrome_dp(s: str) -> str:
    if not s:
        return ""

    n = len(s)
    table = [[False] * n for _ in range(n)]
    max_length = 1
    start = 0

    for i in range(n):
        table[i][i] = True

    for i in range(n-1):
        if s[i] == s[i+1]:
            table[i][i+1] = True
            start = i
            max_length = 2

    for length in range(3, n+1):
        for i in range(n-length+1):
            j = i + length - 1
            if s[i] == s[j] and table[i+1][j-1]:
                table[i][j] = True
                start = i
                max_length = length

    return s[start:start+max_length]

