def build_complete_binary_tree(values):
    if not values:
        return None

    root = TreeNode(values[0])
    q = [root]
    i = 1

    while i < len(values):
        node = q.pop(0)
        if values[i] is not None:
            node.left = TreeNode(values[i])
            q.append(node.left)
        i += 1

        if i < len(values) and values[i] is not None:
            node.right = TreeNode(values[i])
            q.append(node.right)
        i += 1

    return root

def level_order_traversal(root):
    if not root:
        return []

    result = []
    queue = [root]

    while queue:
        current = queue.pop(0)
        result.append(current.val)

        if current.left:
            queue.append(current.left)
        if current.right:
            queue.append(current.right)

    return result

def level_order_complete_binary_tree(values):
    root = build_complete_binary_tree(values)
    return level_order_traversal(root)

