        return 6174
    elif num == 4444:
        return 0
    else:
        num_list = [int(i) for i in str(num)]
        if len(num_list) < 4:
            num_list = num_list + [0] * (4 - len(num_list))
        num_list.sort()
        smallest = int(''.join(map(str, num_list)))
        num_list.sort(reverse=True)
