def find_zero_sum_subarrays(nums: List[int]) -> int:
    n = len(nums)
    max_subarrays = 0
    prefix_sum = [0] * (n + 1)

    for i in range(1, n + 1):
        prefix_sum[i] = prefix_sum[i - 1] + nums[i - 1]

    count = {}
    for i in range(n + 1):
        if prefix_sum[i] in count:
            max_subarrays += count[prefix_sum[i]]
            count[prefix_sum[i]] += 1
        else:
            count[prefix_sum[i]] = 1

    return max_subarrays

def max_subarray_sum_with_target(arr, target):
    max_len = 0
    curr_sum = 0
    sum_dict = {0: -1}
    for i in range(len(arr)):
        curr_sum += arr[i]
        if curr_sum not in sum_dict:
            sum_dict[curr_sum] = i
        if (curr_sum - target) in sum_dict:
            max_len = max(max_len, i - sum_dict[curr_sum - target])
    return target if max_len > 0 else 0

