def find_ways_to_reach_target(d, f, target):
    global count
    if target < d:
        return 0
    count = 0
    def dfs(d, f, target, nowdice, nowsum):
        global count
        if nowdice < d:
            for i in range(1, min(f, target-nowsum)+1):
                dfs(d,f,target,nowdice+1,nowsum+i)

        if nowdice == d and nowsum == target:
            count += 1
    dfs(d,f,target,0,0)
    return count

