def max_in_subarrays(arr, k):
    if not arr or k <= 0:
        return []

    result = []
    window = deque()

    for i, value in enumerate(arr):
        while window and arr[window[-1]] <= value:
            window.pop()
        window.append(i)

        if window[0] <= i - k:
            window.popleft()

        if i + 1 >= k:
            result.append(arr[window[0]])

    return result

