def binary_addition(a, b):
    result = ''
    carry = 0
    i, j = len(a), len(b)
    while i > 0 or j > 0:
        total = carry
        if i > 0:
            total += int(a[i - 1])
            i -= 1
        if j > 0:
            total += int(b[j - 1])
            j -= 1
        if total == 0:
            result = '0' + result
            carry = 0
        elif total == 1:
            result = '1' + result
            carry = 0
        elif total == 2:
            result = '0' + result
            carry = 1
        elif total == 3:
            result = '1' + result
            carry = 1
    if carry != 0:
        result = '1' + result
    return result

from collections import deque

def bridge_crossing(bridge_length, weight, truck_weights):
    time = 0
    bridge = deque([0]*bridge_length)
    truck_weights = deque(truck_weights)

    while truck_weights:
        bridge.pop()
        if sum(bridge) + truck_weights[0] <= weight:
            bridge.appendleft(truck_weights.popleft())
        else:
            bridge.appendleft(0)
        time += 1

    while bridge:
        bridge.pop()
        time += 1

    return time

def binary_search(nums, target):
    if len(nums) == 0:
        return -1
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

def count_occurrence(nums, target):
    first_index = binary_search(nums, target)
    if first_index == -1:
        return 0
    count = 1
    left = first_index - 1
    while left >= 0 and nums[left] == target:
        count += 1
        left -= 1
    right = first_index + 1
    while right < len(nums) and nums[right] == target:
        count += 1
        right += 1
    return count

def occurrence_in_list(nums: list[int], target: int) -> int:
