        if arr[i] == 0:
            count -= 1
        else:
            count += 1

        if count in sum_dict:
            max_length = max(max_length, i - sum_dict[count])
        else:
            sum_dict[count] = i

        if count == 0:
            max_sum = max(max_sum, i + 1)

    return max(max_length, max_sum)

