def max_product_partition(n: int) -> int:
    if n == 2:
        return 1
    if n <= 4:
        return n
    if n % 3 == 0:
        return 3 ** (n // 3)
    if n % 3 == 1:
        return 4 * (3 ** ((n - 4) // 3))
    return 2 * (3 ** ((n - 2) // 3))

from collections import deque


def eventual_safe_states(graph):
    safe = [False for i in range(len(graph))]
    graph = list(map(set, graph))
    reverse_graph = [set() for i in range(len(graph))]
    queue = deque()

    for index, adj in enumerate(graph):
        if not adj:
            queue.append(index)
        for neigh in adj:
            reverse_graph[neigh].add(index)

    while queue:
        current = queue.popleft()
        safe[current] = True
        for neigh in reverse_graph[current]:
            graph[neigh].discard(current)
            if not graph[neigh]:
                queue.append(neigh)

    return [i for i in range(len(safe)) if safe[i]]

