def fib_memoization(n, memo={}):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    try:
        return memo[n]
    except KeyError:
        result = fib_memoization(n-1, memo) + fib_memoization(n-2, memo)
        memo[n] = result
        return result

def longest_alternating_subsequence(nums):
    if not nums:
        return 0

    increasing = [1] * len(nums)
    decreasing = [1] * len(nums)

    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j]:
                increasing[i] = max(increasing[i], decreasing[j] + 1)
            elif nums[i] < nums[j]:
                decreasing[i] = max(decreasing[i], increasing[j] + 1)

    return max(max(increasing), max(decreasing))

def find_replace_string(s, indices, sources, targets):
    ptr, ret = 0, ''
    operations = [(indices[i], sources[i], targets[i]) for i in range(len(indices))]
    operations.sort(key=lambda x: x[0])

    for o in operations:
        i, source, target = o
        ret += s[ptr:i]
        original = s[i:i + len(source)]

        if original == source:
            ret += target
        else:
            ret += original

        ptr = i + len(source)

    if ptr < len(s):
        ret += s[ptr:]

    return ret

