def calculate_extended_gcd(a, b):
    if a == 0:
        return (b, 0, 1)
    gcd, x1, y1 = calculate_extended_gcd(b % a, a)
    x = y1 - (b // a) * x1
    y = x1
    return (gcd, x, y)

from collections import deque

def find_max_sliding_window(nums, k):
    window = deque()
    lista = []

    for i in range(k):
        while window and nums[i] >= nums[window[-1]]:
            window.popleft()
        window.append(i)

    lista.append(nums[window[0]])

    for i in range(k, len(nums)):
        if window[0] <= i - k:
            window.popleft()

        while window and nums[i] >= nums[window[-1]]:
            window.popleft()
        window.append(i)
        lista.append(nums[window[0]])

    return lista

