        if x == len(s1) and y == len(s2):
            return True
        if x < len(s1) and s1[x] == s3[x+y] and (x+1, y) not in visited: 
            temp.append([x+1, y])
            visited.add((x+1, y))
        if y < len(s2) and s2[y] == s3[x+y] and (x, y+1) not in visited:
            temp.append([x, y+1])
            visited.add((x, y+1))
    return False

def sum_Of_Digits(num): 
    sum = 0
    while(num): 
        sum += num % 10
        num = num // 10
    return sum

from datetime import datetime

def diff_days(date1, date2):
    d1 = datetime.strptime(date1, "%Y-%m-%d")
    d2 = datetime.strptime(date2, "%Y-%m-%d")
    delta = d2 - d1
    return abs(delta.days)

def find_closest(sorted_list, target):
    left, right = 0, len(sorted_list) - 1

    while left < right - 1:
        mid = (left + right) // 2
        if sorted_list[mid] == target:
            return sorted_list[mid]
        elif sorted_list[mid] < target:
            left = mid
        else:
            right = mid

    if abs(sorted_list[left] - target) <= abs(sorted_list[right] - target):
        return sorted_list[left]
    return sorted_list[right]

def partition_list(nums, x):
    less = []
    greater = []
    for num in nums:
        if num < x:
            less.append(num)
        else:
            greater.append(num)
    return less + greater

def can_be_non_decreasing(nums):
    modified = False
    for i in range(1, len(nums)):
        if nums[i] < nums[i-1]:
            if modified:
                return False
            if i == 1 or nums[i] >= nums[i-2]:
                nums[i-1] = nums[i]
            elif i == len(nums)-1 or nums[i+1] >= nums[i-1]:
                nums[i] = nums[i-1]
            else:
                return False
            modified = True
    return True

def encodeMessage(plain_text, shift):
    cipher_text = ""
    for char in plain_text:
        if char.isalpha():
            ascii_offset = ord('a') if char.islower() else ord('A')
            cipher_text += chr((ord(char) - ascii_offset + shift) % 26 + ascii_offset)
        else:
            cipher_text += char
    return cipher_text

def sum_nested(lst):
    total = 0
    for i in lst:
        if type(i) == list:
            total += sum_nested(i)
        else:
            total += i
    return total

import math
def find_farthest_point(points):
    farthest = None
    max_distance = 0
    for point in points:
        distance = math.sqrt(point[0]**2 + point[1]**2 + point[2]**2)
        if distance > max_distance:
            max_distance = distance
            farthest = point
    return farthest

def assignment_slots(N, K, T):
    T.sort()
    T = sorted(T, key=lambda x:x[1])
    cnt = 0
    K_time = [1]*K
    for t in T:
        for i in range(t[0]-1,t[1]):
            if K_time[i] == 1:
                K_time[i] = 0
                cnt += 1
                break
    return cnt

def division(dividend, divisor):
    if divisor == 0:
        raise ValueError("Cannot divide by zero")
    if (dividend == -2147483648) and (divisor == -1):
        return 2147483647
    a = abs(dividend)
    b = abs(divisor)
    result = 0
    while a >= b:
        temp = b
        multiple = 1
        while temp <= a:
            a -= temp
            result += multiple
            temp <<= 1
            multiple <<= 1
    if (dividend > 0) == (divisor > 0):
        return result
    else:
        return -result

def find_Max_Sum_Subarray(arr,k):
    if not arr:
        return 0
    max_sum = current_sum = sum(arr[:k])
    for i in range(k,len(arr)):
        current_sum += arr[i] - arr[i-k]
        max_sum = max(max_sum,current_sum)
    return max_sum

def is_perfect_power(n):
    if n < 2:
        return False
    for base in range(2, int(n**0.5) + 1):
        power = 2
        while base**power <= n:
            if base**power == n:
                return True
            power += 1
    return False

def check_symmetric(matrix):
    n = len(matrix)
    if n == 0: return False
    for i in range(n):
        for j in range(n):
            if matrix[i][j] != matrix[j][i]:
                return False
    return True

def count_odd_ends(nums):
  def is_odd_digit(n):
    return n % 2 != 0

  def first_digit(n):
    while n >= 10:
      n //= 10
    return n

  count = 0
  for num in nums:
    if num > 10 and is_odd_digit(first_digit(num)) and is_odd_digit(num % 10):
      count += 1
  return count

def prime_factors_product(n):
    i = 2
    product = 1
    seen = set()
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            if i not in seen:
                product *= i
                seen.add(i)
    if n > 1 and n not in seen:
        product *= n
    return product

from collections import defaultdict
from heapq import heapify, heappop

def longest_path_in_matrix(matrix):
    if not matrix:
        return 0

    num_rows = len(matrix)
    num_cols = len(matrix[0])

    indices = defaultdict(list)
    seen = []
    for i in range(num_rows):
        for j in range(num_cols):
            indices[matrix[i][j]].append((i, j))
            seen.append(-matrix[i][j])

    dp = [x[:] for x in [[1] * num_cols] * num_rows]
    heapify(seen)

    while seen:
        n = -heappop(seen)
        if n in indices:
            for i, j in indices[n]:
                if i > 0 and matrix[i-1][j] > n:
                    dp[i][j] = max(dp[i-1][j]+1, dp[i][j])
                if j > 0 and matrix[i][j-1] > n:
                    dp[i][j] = max(dp[i][j-1]+1, dp[i][j])
                if i < num_rows-1 and matrix[i+1][j] > n:
                    dp[i][j] = max(dp[i+1][j]+1, dp[i][j])
                if j < num_cols-1 and matrix[i][j+1] > n:
                    dp[i][j] = max(dp[i][j+1]+1, dp[i][j])

    return max([max(row) for row in dp])

# Definition for a binary tree node.
class TreeNode(object):
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def insert(nums, idx=1):
    if idx > len(nums):
        return None
    elif nums[idx-1] is None:
        return None
    root = TreeNode(nums[idx-1])
    root.left = insert(nums, idx*2)
    root.right = insert(nums, idx*2+1)
    return root

def isBalanced(root):
    if not root:
        return True
    root = insert(root)
    def height(node, left=0, right=0):
        if node:
            if node.left:
                left = height(node.left)
            if left == -1:
                return -1
            if node.right:
                right = height(node.right)
            if right == -1:
                return -1
            if abs(left - right) <= 1:
                return max(left, right) + 1
            return -1
        return 0
    return height(root) != -1
